def is_nested(s):
    # First validate the whole string as a balanced bracket sequence.
    depth = 0
    for ch in s:
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
            if depth < 0:
                return False
    if depth != 0:
        return False

    # Then check whether there is at least one nested pair: a '[' inside another '['.
    depth = 0
    for ch in s:
        if ch == '[':
            depth += 1
            if depth >= 2:
                return True
        elif ch == ']':
            depth -= 1
    return False

# Tests
print(is_nested('[[]]'))            # True
print(is_nested('[]]]]]]][[[[[]'))  # False
print(is_nested('[][]'))            # False
print(is_nested('[]'))              # False
print(is_nested('[[][]]'))          # True
print(is_nested('[[]][['))          # False
